struct Entry { word: Str, count: Int }

fn count_words(text: Bytes) -> HashMap<Str, Int> {
  let mut counts: HashMap<Str, Int> = HashMap::new();
  let mut cur = "".to_bytes();
  let n = text.len();
  for i in 0..(n + 1) {
    let mut c = -1;
    if i < n { c = text[i]; }
    let mut letter = -1;
    if c >= 65 && c <= 90 {
      letter = c + 32;
    } else if c >= 97 && c <= 122 {
      letter = c;
    }
    if letter >= 0 {
      cur.push(letter);
    } else if cur.len() > 0 {
      let w = cur.to_str();
      let prev = counts.get(w).unwrap_or(0);
      counts.insert(w, prev + 1);
      cur = "".to_bytes();
    }
  }
  counts
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("text.txt")?;
  let counts = count_words(text);
  let mut entries: List<Entry> = [];
  for k in counts.keys() {
    entries.push(Entry { word: k, count: counts.get(k).unwrap_or(0) });
  }
  entries.sort_by(|a: Entry, b: Entry| {
    if a.count != b.count { a.count > b.count } else { a.word < b.word }
  });
  let mut lines: List<Str> = [];
  let m = entries.len().min(5);
  for i in 0..m {
    lines.push(entries[i].word + " " + entries[i].count.to_str());
  }
  Ok(lines.join("\n"))
}

struct Agg { region: Str, qty: Int, rev: Int }

fn fmt_cents(c: Int) -> Str {
  let neg = c < 0;
  let a = if neg { 0 - c } else { c };
  let whole = a / 100;
  let frac = a % 100;
  let fs = if frac < 10 { "0" + frac.to_str() } else { frac.to_str() };
  let s = whole.to_str() + "." + fs;
  if neg { "-" + s } else { s }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let mut aggs: HashMap<Str, Agg> = HashMap::new();
  let mut skipped = 0;
  let mut seen_header = false;
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    if !seen_header { seen_header = true; continue; }
    let parts = line.split(",");
    if parts.len() != 5 { skipped += 1; continue; }
    let region = parts[1].trim();
    let Some(q) = parts[3].trim().parse_int() else { skipped += 1; continue; };
    let Some(u) = parts[4].trim().parse_int() else { skipped += 1; continue; };
    let cur = aggs.get(region).unwrap_or(Agg { region: region, qty: 0, rev: 0 });
    aggs.insert(region, Agg { region: region, qty: cur.qty + q, rev: cur.rev + q * u });
  }
  let mut list: List<Agg> = [];
  for k in aggs.keys() {
    let Some(a) = aggs.get(k) else { continue; };
    list.push(a);
  }
  list.sort_by(|a, b| a.rev > b.rev || (a.rev == b.rev && a.region < b.region));
  let mut out: List<Str> = [];
  for a in list {
    out.push(a.region + " " + a.qty.to_str() + " " + fmt_cents(a.rev));
  }
  out.push("skipped " + skipped.to_str());
  Ok(out.join("\n"))
}

struct Entry { ip: Str, path: Str, status: Int, size: Int }

fn parse_line(raw: Str) -> Option<Entry> {
  let line = raw.trim();
  let q1 = line.find("\"")?;
  let prefix = line.slice(0, q1);
  if !prefix.ends_with("] ") { return None; }
  if !prefix.contains(" [") { return None; }
  let head = prefix.split(" ");
  if head.len() < 4 { return None; }
  let ip = head[0];
  if ip.len() == 0 { return None; }
  let after = line.slice(q1 + 1, line.len());
  let q2 = after.find("\"")?;
  let request = after.slice(0, q2);
  let rest = after.slice(q2 + 1, after.len());
  if !rest.starts_with(" ") { return None; }
  let tail = rest.trim().split(" ");
  if tail.len() != 2 { return None; }
  let status = tail[0].parse_int()?;
  if status < 100 || status > 999 { return None; }
  let size = if tail[1] == "-" { 0 } else { tail[1].parse_int()? };
  if size < 0 { return None; }
  let req = request.split(" ");
  if req.len() != 3 { return None; }
  let full = req[1];
  if full.len() == 0 { return None; }
  let path = match full.find("?") {
    Some(i) => full.slice(0, i),
    None => full,
  };
  Some(Entry { ip: ip, path: path, status: status, size: size })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;
  for line in text.lines() {
    let Some(e) = parse_line(line) else { continue; };
    statuses.insert(e.status, statuses.get(e.status).unwrap_or(0) + 1);
    paths.insert(e.path, paths.get(e.path).unwrap_or(0) + 1);
    total = total + e.size;
    if e.status >= 500 && e.status <= 599 {
      errs.insert(e.ip, errs.get(e.ip).unwrap_or(0) + 1);
    }
  }
  let mut out: List<Str> = [];
  for s in statuses.keys() {
    out.push(s.to_str() + " " + statuses.get(s).unwrap_or(0).to_str());
  }
  out.push("bytes " + total.to_str());
  let mut best = "";
  let mut best_n = 0;
  for p in paths.keys() {
    let n = paths.get(p).unwrap_or(0);
    if n > best_n {
      best = p;
      best_n = n;
    }
  }
  if best_n > 0 {
    out.push("top " + best + " " + best_n.to_str());
  }
  let mut ips = errs.keys();
  let counts = errs;
  ips.sort_by(|a, b| {
    let ca = counts.get(a).unwrap_or(0);
    let cb = counts.get(b).unwrap_or(0);
    ca > cb || (ca == cb && a < b)
  });
  for ip in ips {
    out.push("errors " + ip + " " + counts.get(ip).unwrap_or(0).to_str());
  }
  Ok(out.join("\n"))
}

fn order_total(o: Json) -> Int {
  let items = o.get("items").and_then(|j| j.as_list()).unwrap_or([]);
  let mut t = 0;
  for it in items {
    let q = it.get("qty").and_then(|j| j.as_int()).unwrap_or(0);
    let p = it.get("price_cents").and_then(|j| j.as_int()).unwrap_or(0);
    t = t + q * p;
  }
  t
}

fn read_text(input: Dir) -> Result<Str, Str> {
  match input.read("orders.json") {
    Ok(b) => Ok(b.to_str()),
    Err(_) => Err("cannot read orders.json"),
  }
}

fn main(input: Dir) -> Result<Str, Str> {
  let text = read_text(input)?;
  let doc = text.parse_json()?;
  let orders = doc.as_list().ok_or("orders.json is not an array")?;
  let mut counts: Map<Str, Int> = Map::new();
  let mut totals: Map<Str, Int> = Map::new();
  let mut ref_n = 0;
  let mut ref_t = 0;
  let mut pend_n = 0;
  for o in orders {
    let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
    let cust = o.get("customer").and_then(|j| j.as_str()).unwrap_or("");
    let t = order_total(o);
    match status {
      "paid" => {
        let c = counts.get(cust).unwrap_or(0);
        counts.insert(cust, c + 1);
        let s = totals.get(cust).unwrap_or(0);
        totals.insert(cust, s + t);
      }
      "refunded" => {
        ref_n = ref_n + 1;
        ref_t = ref_t + t;
      }
      "pending" => {
        pend_n = pend_n + 1;
      }
      _ => {}
    }
  }
  let mut lines: List<Str> = [];
  for k in counts.keys() {
    let c = counts.get(k).unwrap_or(0);
    let s = totals.get(k).unwrap_or(0);
    lines.push(k + " " + c.to_str() + " " + s.to_str());
  }
  lines.push("refunded " + ref_n.to_str() + " " + ref_t.to_str());
  lines.push("pending " + pend_n.to_str());
  Ok(lines.join("\n"))
}

fn normalize(line: Str) -> Option<Str> {
  let parts = line.split("@");
  if parts.len() != 2 { return None; }
  let mut local = parts[0];
  let domain = parts[1];
  if local.len() == 0 { return None; }
  if !domain.contains(".") { return None; }
  if domain.starts_with(".") || domain.ends_with(".") { return None; }
  if domain == "gmail.com" {
    local = local.split("+")[0];
    local = local.replace(".", "");
  }
  Some(local + "@" + domain)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("emails.txt")?.to_str();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut invalid = 0;
  for raw in text.lines() {
    let line = raw.trim().to_lowercase();
    if line.len() == 0 { continue; }
    match normalize(line) {
      Some(a) => { seen.insert(a, true); }
      None => { invalid += 1; }
    }
  }
  let mut out = "";
  for k in seen.keys() {
    out = out + k + "\n";
  }
  out = out + "invalid " + invalid.to_str();
  Ok(out)
}

fn to_roman(n: Int) -> Str {
  let vals = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut rest = n;
  let mut out = "";
  for i in 0..vals.len() {
    while rest >= vals[i] {
      out = out + syms[i];
      rest = rest - vals[i];
    }
  }
  out
}

fn letter_value(b: Int) -> Int {
  match b {
    73 => 1,
    86 => 5,
    88 => 10,
    76 => 50,
    67 => 100,
    68 => 500,
    77 => 1000,
    _ => 0,
  }
}

fn from_roman(s: Str) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() == 0 { return None; }
  let mut vals: List<Int> = [];
  for i in 0..b.len() {
    let v = letter_value(b[i]);
    if v == 0 { return None; }
    vals.push(v);
  }
  let mut total = 0;
  for i in 0..vals.len() {
    if i + 1 < vals.len() && vals[i] < vals[i + 1] {
      total = total - vals[i];
    } else {
      total = total + vals[i];
    }
    if total > 100000 { return None; }
  }
  if total < 1 || total > 3999 { return None; }
  if to_roman(total) == s { Some(total) } else { None }
}

fn convert(line: Str) -> Str {
  if let Some(n) = line.parse_int() {
    if n >= 1 && n <= 3999 {
      return to_roman(n);
    }
    return "invalid";
  }
  match from_roman(line) {
    Some(v) => v.to_str(),
    None => "invalid",
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("numbers.txt")?.to_str();
  let mut out: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    out.push(line + " = " + convert(line));
  }
  Ok(out.join("\n"))
}

fn closer(c: Int) -> Str {
  if c == 40 { ")" } else if c == 91 { "]" } else { "}" }
}

fn check(line: Str) -> Str {
  let b = line.to_bytes();
  let mut stack: List<Int> = [];
  for i in 0..b.len() {
    let c = b[i];
    if c == 40 || c == 91 || c == 123 {
      stack.push(c);
    } else if c == 41 || c == 93 || c == 125 {
      let found = line.slice(i, i + 1);
      let col = (i + 1).to_str();
      match stack.pop() {
        None => { return "col " + col + ": unexpected " + found; }
        Some(o) => {
          let exp = closer(o);
          if exp != found {
            return "col " + col + ": expected " + exp + ", found " + found;
          }
        }
      }
    }
  }
  if stack.len() > 0 {
    "unclosed " + closer(stack[stack.len() - 1])
  } else {
    "ok"
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("snippets.txt")?.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    out.push(check(line));
  }
  Ok(out.join("\n"))
}

fn rank(p: Int, n: Int) -> Int {
  let r = (p * n + 99) / 100;
  if r < 1 { 0 } else { r - 1 }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("timings.log")?.to_str();
  let mut groups: Map<Str, Map<Str, List<Int>>> = Map::new();
  for raw in text.lines() {
    let line = raw.replace("\t", " ").replace("\r", " ");
    let parts = line.split(" ").filter(|s| s.len() > 0);
    if parts.len() != 3 { continue; }
    let Some(ms) = parts[2].parse_int() else { continue; };
    let method = parts[0];
    let path = parts[1];
    let mut inner: Map<Str, List<Int>> = groups.get(method).unwrap_or(Map::new());
    let mut ts: List<Int> = inner.get(path).unwrap_or([]);
    ts.push(ms);
    inner.insert(path, ts);
    groups.insert(method, inner);
  }
  let mut out: List<Str> = [];
  for m in groups.keys() {
    let inner: Map<Str, List<Int>> = groups.get(m).unwrap_or(Map::new());
    for p in inner.keys() {
      let mut ts: List<Int> = inner.get(p).unwrap_or([]);
      ts.sort();
      let n = ts.len();
      if n == 0 { continue; }
      let p50 = ts[rank(50, n)];
      let p95 = ts[rank(95, n)];
      let mx = ts[n - 1];
      out.push(m + " " + p + " count=" + n.to_str() + " p50=" + p50.to_str()
        + " p95=" + p95.to_str() + " max=" + mx.to_str());
    }
  }
  Ok(out.join("\n"))
}

struct Edge { to: Int, w: Int }
struct Item { d: Int, v: Int }
struct Trip { a: Str, b: Str }

fn words(line: Str) -> List<Str> {
  line.replace("\t", " ").replace("\r", " ").split(" ").filter(|s| s.len() > 0)
}

fn dijkstra(adj: List<List<Edge>>, src: Int) -> List<Int> {
  let n = adj.len();
  let mut dist: List<Int> = [];
  for i in 0..n { dist.push(-1); }
  let mut done: List<Bool> = [];
  for i in 0..n { done.push(false); }
  let mut h: List<Item> = [];
  dist[src] = 0;
  h.push(Item { d: 0, v: src });
  while h.len() > 0 {
    let top = h[0];
    let last = h.pop().unwrap_or(top);
    if h.len() > 0 {
      h[0] = last;
      let mut i = 0;
      let m = h.len();
      loop {
        let l = 2 * i + 1;
        let r = 2 * i + 2;
        let mut s = i;
        if l < m && h[l].d < h[s].d { s = l; }
        if r < m && h[r].d < h[s].d { s = r; }
        if s == i { break; }
        let t = h[i];
        h[i] = h[s];
        h[s] = t;
        i = s;
      }
    }
    let u = top.v;
    if done[u] { continue; }
    if top.d != dist[u] { continue; }
    done[u] = true;
    for e in adj[u] {
      let nd = top.d + e.w;
      if dist[e.to] == -1 || nd < dist[e.to] {
        dist[e.to] = nd;
        h.push(Item { d: nd, v: e.to });
        let mut i = h.len() - 1;
        while i > 0 {
          let p = (i - 1) / 2;
          if h[p].d <= h[i].d { break; }
          let t = h[i];
          h[i] = h[p];
          h[p] = t;
          i = p;
        }
      }
    }
  }
  dist
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut ids: HashMap<Str, Int> = HashMap::new();
  let mut names: List<Str> = [];
  let mut adj: List<List<Edge>> = [];
  let mut trips: List<Trip> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 || t.starts_with("#") { continue; }
    let w = words(t);
    if w.len() == 4 && w[0] == "road" {
      let Some(c) = w[3].parse_int() else { continue; };
      let mut ends: List<Int> = [];
      for k in 1..3 {
        let nm = w[k];
        let id = match ids.get(nm) {
          Some(i) => i,
          None => {
            let i = names.len();
            ids.insert(nm, i);
            names.push(nm);
            adj.push([]);
            i
          }
        };
        ends.push(id);
      }
      let a = ends[0];
      let b = ends[1];
      adj[a].push(Edge { to: b, w: c });
      adj[b].push(Edge { to: a, w: c });
    } else if w.len() == 3 && w[0] == "trip" {
      trips.push(Trip { a: w[1], b: w[2] });
    }
  }
  let mut cache: HashMap<Int, List<Int>> = HashMap::new();
  let mut out: List<Str> = [];
  for t in trips {
    if t.a == t.b { out.push(t.a + " 0"); continue; }
    let ia = ids.get(t.a);
    let ib = ids.get(t.b);
    let (Some(x), Some(y)) = (ia, ib) else { out.push(t.a + " " + t.b + " unreachable"); continue; };
    let dist = match cache.get(y) {
      Some(d) => d,
      None => {
        let d = dijkstra(adj, y);
        cache.insert(y, d);
        d
      }
    };
    if dist[x] == -1 { out.push(t.a + " " + t.b + " unreachable"); continue; }
    let mut path: List<Str> = [names[x]];
    let mut u = x;
    while u != y {
      let mut best = -1;
      for e in adj[u] {
        if dist[e.to] != -1 && dist[e.to] + e.w == dist[u] {
          if best == -1 || names[e.to] < names[best] { best = e.to; }
        }
      }
      u = best;
      path.push(names[u]);
    }
    out.push(path.join(" -> ") + " " + dist[x].to_str());
  }
  Ok(out.join("\n"))
}

