fn dijkstra(adj: List<List<Edge>>, src: Int) -> List<Int> {
  let n = adj.len();
  let mut dist: List<Int> = [];
  for i in 0..n { dist.push(-1); }
  let mut done: List<Bool> = [];
  for i in 0..n { done.push(false); }
  let mut h: List<Item> = [];
  dist[src] = 0;
  h.push(Item { d: 0, v: src });
  while h.len() > 0 {
    let top = h[0];
