  let text = input.read("routes.txt")?.to_str();
  let mut ids: HashMap<Str, Int> = HashMap::new();
  let mut names: List<Str> = [];
  let mut adj: List<List<Edge>> = [];
  let mut trips: List<Trip> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 || t.starts_with("#") { continue; }
    let w = words(t);
    if w.len() == 4 && w[0] == "road" {
      let Some(c) = w[3].parse_int() else { continue; };
      let mut ends: List<Int> = [];
      for k in 1..3 {
        let nm = w[k];
        let id = match ids.get(nm) {
          Some(i) => i,
          None => {
            let i = names.len();
            ids.insert(nm, i);
            names.push(nm);
            adj.push([]);
            i
          }
        };
        ends.push(id);
      }
      let a = ends[0];
      let b = ends[1];
      adj[a].push(Edge { to: b, w: c });
      adj[b].push(Edge { to: a, w: c });
