    let Some(y) = ids.get(t.b) else { out.push(t.a + " " + t.b + " unreachable"); continue; };
    let dist = match cache.get(y) {
      Some(d) => d,
      None => {
        let d = dijkstra(adj, y);
        cache.insert(y, d);
        d
      }
    };
    if dist[x] == -1 { out.push(t.a + " " + t.b + " unreachable"); continue; }
