        }
      }
      u = best;
      path.push(names[u]);
    }
    out.push(path.join(" -> ") + " " + dist[x].to_str());
  }
  Ok(out.join("\n"))
}

struct Leaf { path: Str, val: Str }

fn merge(base: Map<Str, Json>, ov: Map<Str, Json>) -> Map<Str, Json> {
  let mut out = base;
  for k in ov.keys() {
    let Some(v) = ov.get(k) else { continue; };
    match v {
      Json::Null => { out.remove(k); }
      Json::Obj(o) => {
        let mut b: Map<Str, Json> = Map::new();
        if let Some(Json::Obj(bo)) = out.get(k) {
          b = bo;
        }
        out.insert(k, Json::Obj(merge(b, o)));
      }
      other => { out.insert(k, other); }
    }
  }
  out
}

fn join_path(prefix: Str, k: Str) -> Str {
  if prefix == "" { k } else { prefix + "." + k }
}

fn flat(prefix: Str, j: Json, acc: List<Leaf>) -> List<Leaf> {
  let mut out = acc;
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        out.push(Leaf { path: prefix, val: "{}" });
      } else {
        for k in m.keys() {
          let Some(v) = m.get(k) else { continue; };
          out = flat(join_path(prefix, k), v, out);
        }
      }
    }
    Json::Arr(xs) => {
      if xs.len() == 0 {
        out.push(Leaf { path: prefix, val: "[]" });
      } else {
        for i in 0..xs.len() {
          out = flat(join_path(prefix, i.to_str()), xs[i], out);
        }
      }
    }
    other => {
      out.push(Leaf { path: prefix, val: other.to_json() });
    }
  }
  out
}

fn read_obj(input: Dir, name: Str) -> Result<Map<Str, Json>, Str> {
  let bytes = input.read(name).map_err(|e| "cannot read " + name)?;
  let text = bytes.to_str();
  let j = text.parse_json()?;
  match j {
    Json::Obj(m) => Ok(m),
    _ => Err(name + " is not an object"),
  }
}

fn main(input: Dir) -> Result<Str, Str> {
  let base = read_obj(input, "base.json")?;
  let ov = read_obj(input, "override.json")?;
  let merged = merge(base, ov);
  let mut leaves: List<Leaf> = [];
  for k in merged.keys() {
    let Some(v) = merged.get(k) else { continue; };
    leaves = flat(k, v, leaves);
  }
  leaves.sort_by_key(|l| l.path);
  let lines = leaves.map(|l| l.path + "=" + l.val);
  Ok(lines.join("\n"))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();
  let mut err_out = "";
  let mut warn_out = "";
  let mut info_out = "";
  let mut n_err = 0;
  let mut n_warn = 0;
  let mut n_info = 0;
  let mut n_other = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let fields = line.trim().split(" ").filter(|p| p != "");
    if fields.len() < 3 {
      n_other += 1;
      continue;
    }
    let level = fields[1].to_lowercase();
    if level == "error" {
      err_out = err_out + line + "\n";
      n_err += 1;
    } else if level == "warn" || level == "warning" {
      warn_out = warn_out + line + "\n";
      n_warn += 1;
    } else if level == "info" {
      info_out = info_out + line + "\n";
      n_info += 1;
    } else {
      n_other += 1;
    }
  }
  out.write("error.log", err_out.to_bytes())?;
  out.write("warn.log", warn_out.to_bytes())?;
  out.write("info.log", info_out.to_bytes())?;
  Ok("error " + n_err.to_str() + "\nwarn " + n_warn.to_str() + "\ninfo " + n_info.to_str() + "\nother " + n_other.to_str())
}

struct Entry { size: Int, lines: Int }

fn count_lines(b: Bytes) -> Int {
  let n = b.len();
  let mut c = 0;
  for i in 0..n {
    if b[i] == 10 { c += 1; }
  }
  if n > 0 && b[n - 1] != 10 { c += 1; }
  c
}

fn collect(d: Dir) -> Result<Map<Str, Entry>, IoErr> {
  let mut files: Map<Str, Entry> = Map::new();
  let mut stack: List<Str> = [""];
  loop {
    let Some(dir) = stack.pop() else { break; };
    let names = d.list(dir)?;
    for name in names {
      if let Some(sub) = name.strip_suffix("/") {
        if dir == "" {
          stack.push(sub);
        } else {
          stack.push(dir + "/" + sub);
        }
      } else {
        let path = if dir == "" { name } else { dir + "/" + name };
        let data = d.read(path)?;
        files.insert(path, Entry { size: data.len(), lines: count_lines(data) });
      }
    }
  }
  Ok(files)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let files = collect(input)?;
  let mut csv = "path,bytes,lines\n";
  let mut total = 0;
  let mut count = 0;
  for p in files.keys() {
    let Some(e) = files.get(p) else { continue; };
    csv = csv + p + "," + e.size.to_str() + "," + e.lines.to_str() + "\n";
    total += e.size;
    count += 1;
  }
  out.create("index.csv", csv.to_bytes())?;
  Ok("files " + count.to_str() + " bytes " + total.to_str())
}

fn parse_line(line: Str) -> Option<List<Str>> {
  let b = line.to_bytes();
  let n = b.len();
  let mut fields: List<Str> = [];
  let mut cur = "".to_bytes();
  let mut in_q = false;
  let mut at_start = true;
  let mut i = 0;
  while i < n {
    let c = b[i];
    if in_q {
      if c == 34 {
        if i + 1 < n && b[i + 1] == 34 {
          cur.push(34);
          i = i + 2;
          continue;
        }
        in_q = false;
      } else {
        cur.push(c);
      }
      i = i + 1;
      continue;
    }
    if c == 44 {
      fields.push(cur.to_str());
      cur = "".to_bytes();
      at_start = true;
    } else if c == 34 && at_start {
      in_q = true;
      at_start = false;
    } else {
      cur.push(c);
      at_start = false;
    }
    i = i + 1;
  }
  if in_q {
    return None;
  }
  fields.push(cur.to_str());
  Some(fields)
}

fn tags_json(s: Str) -> Json {
  let mut out: List<Json> = [];
  for t in s.split(";") {
    let tt = t.trim();
    if tt.len() > 0 {
      out.push(Json::Str(tt));
    }
  }
  Json::Arr(out)
}

fn row_json(f: List<Str>) -> Option<Json> {
  if f.len() != 5 {
    return None;
  }
  let id = f[0].trim().parse_int()?;
  let a = f[3].trim().to_lowercase();
  let active = a == "yes" || a == "true" || a == "1";
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("name", Json::Str(f[1]));
  m.insert("email", Json::Str(f[2]));
  m.insert("active", Json::Bool(active));
  m.insert("tags", tags_json(f[4]));
  Some(Json::Obj(m))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let raw = input.read("users.csv")?;
  let mut data = raw;
  if raw.len() >= 3 && raw[0] == 239 && raw[1] == 187 && raw[2] == 191 {
    data = raw.slice(3, raw.len());
  }
  let text = data.to_str();
  let mut rows: List<Json> = [];
  let mut skipped = 0;
  let mut seen_header = false;
  for l in text.lines() {
    let mut line = l;
    if let Some(s) = line.strip_suffix("\r") {
      line = s;
    }
    if line.trim() == "" {
      continue;
    }
    if !seen_header {
      seen_header = true;
      continue;
    }
    let mut ok = false;
    if let Some(fields) = parse_line(line) {
      if let Some(j) = row_json(fields) {
        rows.push(j);
        ok = true;
      }
    }
    if !ok {
      skipped = skipped + 1;
    }
  }
  let n = rows.len();
  out.write("users.json", Json::Arr(rows).to_json().to_bytes())?;
  Ok("rows " + n.to_str() + " skipped " + skipped.to_str())
}

fn normalize(name: Str) -> Str {
  let b = name.to_lowercase().to_bytes();
  let mut out = "".to_bytes();
  let mut pending = false;
  let mut i = 0;
  while i < b.len() {
    let c = b[i];
    let ok = (c >= 97 && c <= 122) || (c >= 48 && c <= 57) || c == 46;
    if ok {
      if pending {
        out.push(45);
        pending = false;
      }
      out.push(c);
    } else {
      if out.len() > 0 {
        pending = true;
      }
    }
    i = i + 1;
  }
  out.to_str()
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut taken: HashMap<Str, Bool> = HashMap::new();
  let mut lines: List<Str> = [];
  for name in names {
    if name.ends_with("/") { continue; }
    let n = normalize(name);
    if n.len() == 0 || taken.get(n).is_some() {
      lines.push(name + " skipped");
      continue;
    }
    taken.insert(n, true);
    let data = input.read(name)?;
    out.create(n, data)?;
    lines.push(name + " -> " + n);
  }
  Ok(lines.join("\n"))
}

fn is_part(name: Str) -> Bool {
  if name.len() != 13 { return false; }
  if !name.starts_with("part-") { return false; }
  if !name.ends_with(".txt") { return false; }
  let b = name.to_bytes();
  for i in 5..9 {
    let c = b[i];
    if c < 48 || c > 57 { return false; }
  }
  true
}

fn parse_part(text: Str) -> Option<List<Int>> {
  let mut vals: List<Int> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    let n = t.parse_int()?;
    vals.push(n);
  }
  Some(vals)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut seen: Map<Int, Bool> = Map::new();
  let mut parts = 0;
  let mut corrupt = 0;
  for name in names {
    if !is_part(name) { continue; }
    parts += 1;
    let bytes = input.read(name)?;
    let raw = bytes.to_str();
    match parse_part(raw) {
      Some(vals) => {
        for v in vals { seen.insert(v, true); }
      }
      None => { corrupt += 1; }
    }
  }
  let keys = seen.keys();
  let mut text = "";
  for k in keys { text = text + k.to_str() + "\n"; }
  out.write("merged.txt", text.to_bytes())?;
  Ok("parts " + parts.to_str() + " corrupt " + corrupt.to_str() + " values " + seen.len().to_str())
}

fn main(src: Dir, dst: Dir) -> Result<Str, IoErr> {
  let src_names = src.list("")?;
  let dst_names = dst.list("")?;
  let mut dst_set: HashMap<Str, Bool> = HashMap::new();
  for n in dst_names {
    if !n.ends_with("/") { dst_set.insert(n, true); }
  }
  let mut src_set: HashMap<Str, Bool> = HashMap::new();
  let mut names: List<Str> = [];
  for n in src_names {
    if !n.ends_with("/") {
      src_set.insert(n, true);
      names.push(n);
    }
  }
  names.sort();
  let mut lines: List<Str> = [];
  for n in names {
    let data = src.read(n)?;
    if dst_set.get(n).is_some() {
      let old = dst.read(n)?;
      if old == data {
        lines.push("same " + n);
      } else {
        dst.write(n, data)?;
        lines.push("updated " + n);
      }
    } else {
      dst.write(n, data)?;
      lines.push("added " + n);
    }
  }
  let mut kept = 0;
  for k in dst_set.keys() {
    if src_set.get(k).is_none() { kept += 1; }
  }
  lines.push("kept " + kept.to_str());
  Ok(lines.join("\n"))
}

struct Entry { page: Str, total: Int }

const PREFIX: Str = "page:";

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let text = input.read("visits.txt").map_err(|e| "cannot read visits.txt")?.to_str();

  let mut local: Map<Str, Int> = Map::new();
  for line in text.lines() {
    let p = line.trim();
    if p.len() == 0 { continue; }
    let c = local.get(p).unwrap_or(0);
    local.insert(p, c + 1);
  }

  for p in local.keys() {
    let n = local.get(p).unwrap_or(0);
    counts.add(PREFIX + p, n).map_err(|e| "cannot update counts")?;
  }

  let mut entries: List<Entry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = counts.scan(PREFIX, after, 1000).map_err(|e| "cannot read counts")?;
    for kv in page {
      let name = kv.key.strip_prefix(PREFIX).unwrap_or(kv.key);
      let total = kv.value.to_str().trim().parse_int().unwrap_or(0);
      entries.push(Entry { page: name, total: total });
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }

  entries.sort_by(|a, b| a.total > b.total || (a.total == b.total && a.page < b.page));

  let mut lines: List<Str> = [];
  for e in entries {
    lines.push(e.page + " " + e.total.to_str());
  }
  Ok(lines.join("\n"))
}

struct User { name: Str, email: Str }

fn key(id: Str) -> Str { "u:" + id }

fn kerr(e: KvErr) -> Str { "kv error" }

fn load(users: Kv, id: Str) -> Result<Option<User>, Str> {
  let v = users.get(key(id)).map_err(kerr)?;
  let Some(b) = v else { return Ok(None); };
  let j = b.to_str().parse_json()?;
  let name = j.get("name").and_then(|x| x.as_str()).unwrap_or("");
  let email = j.get("email").and_then(|x| x.as_str()).unwrap_or("");
  Ok(Some(User { name: name, email: email }))
}

fn store(users: Kv, id: Str, u: User) -> Result<(), Str> {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(u.name));
  m.insert("email", Json::Str(u.email));
  users.set(key(id), Json::Obj(m).to_json().to_bytes()).map_err(kerr)
}

fn js(s: Str) -> Str { Json::Str(s).to_json() }

fn process(users: Kv, line: Str) -> Result<Option<Str>, Str> {
  let t = line.trim();
  if t.len() == 0 { return Ok(None); }
  let parts = t.split(" ").filter(|p| p.len() > 0);
  let bad = "bad " + t;
  let cmd = parts[0];
  let n = parts.len();
  if cmd == "put" && n == 4 {
    store(users, parts[1], User { name: parts[2], email: parts[3] })?;
    return Ok(Some("ok " + parts[1]));
  }
  if cmd == "rename" && n == 3 {
    let id = parts[1];
    match load(users, id)? {
      Some(u) => {
        store(users, id, User { name: parts[2], ..u })?;
        return Ok(Some("ok " + id));
      }
      None => { return Ok(Some("missing " + id)); }
    }
  }
  if cmd == "get" && n == 2 {
    let id = parts[1];
    match load(users, id)? {
      Some(u) => {
        return Ok(Some("{\"id\":" + js(id) + ",\"name\":" + js(u.name) + ",\"email\":" + js(u.email) + "}"));
      }
      None => { return Ok(Some("missing " + id)); }
    }
  }
  if cmd == "del" && n == 2 {
    let id = parts[1];
    match load(users, id)? {
      Some(_) => {
        users.delete(key(id)).map_err(kerr)?;
        return Ok(Some("ok " + id));
      }
      None => { return Ok(Some("missing " + id)); }
    }
  }
  if cmd == "count" && n == 1 {
    let ks = users.keys("u:").map_err(kerr)?;
    return Ok(Some("count " + ks.len().to_str()));
  }
  Ok(Some(bad))
}

fn main(input: Dir, users: Kv) -> Result<Str, Str> {
  let data = input.read("commands.txt").map_err(|e| "cannot read commands.txt")?;
  let text = data.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    if let Some(s) = process(users, line)? {
      out.push(s);
    }
  }
  Ok(out.join("\n"))
}

struct Ev { id: Str, account: Str, cents: Int }

struct Rec { account: Str, cents: Int }

fn kv_msg(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv error: too large",
    KvErr::Full => "kv error: store full",
    KvErr::NotInt => "kv error: not an integer",
    KvErr::Overflow => "kv error: overflow",
  }
}

fn io_msg(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "io error: not found",
    IoErr::Denied => "io error: denied",
    IoErr::TooLarge => "io error: too large",
    IoErr::InvalidPath => "io error: invalid path",
    IoErr::Exists => "io error: exists",
  }
}

fn seen_key(id: Str) -> Str { "seen/" + id.sha256().to_hex() }

fn acct_key(a: Str) -> Str { "acct/" + a.sha256().to_hex() }

fn parse_ev(line: Str) -> Option<Ev> {
  let j = line.parse_json().ok()?;
  let Json::Obj(m) = j else { return None; };
  let Some(Json::Str(id)) = m.get("id") else { return None; };
  let Some(Json::Str(account)) = m.get("account") else { return None; };
  let Some(Json::Num(cents)) = m.get("cents") else { return None; };
  Some(Ev { id: id, account: account, cents: cents })
}

fn encode_rec(r: Rec) -> Bytes {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("a", Json::Str(r.account));
  m.insert("c", Json::Num(r.cents));
  Json::Obj(m).to_json().to_bytes()
}

fn decode_rec(b: Bytes) -> Option<Rec> {
  let j = b.to_str().parse_json().ok()?;
  let a = j.get("a")?.as_str()?;
  let c = j.get("c")?.as_int()?;
  Some(Rec { account: a, cents: c })
}

// Returns true if applied, false if duplicate.
fn apply(state: Kv, e: Ev) -> Result<Bool, KvErr> {
  let claimed = state.swap(seen_key(e.id), None, Some("1".to_bytes()))?;
  if !claimed { return Ok(false); }
  let k = acct_key(e.account);
  let mut bal = 0;
  if let Some(b) = state.get(k)? {
    if let Some(r) = decode_rec(b) {
      bal = r.cents;
    }
  }
  bal = bal + e.cents;
  state.set(k, encode_rec(Rec { account: e.account, cents: bal }))?;
  Ok(true)
}

fn balances(state: Kv) -> Result<Map<Str, Int>, KvErr> {
  let mut out: Map<Str, Int> = Map::new();
  let mut after: Option<Str> = None;
  loop {
    let page = state.scan("acct/", after, 1000)?;
    for ent in page {
      if let Some(r) = decode_rec(ent.value) {
        out.insert(r.account, r.cents);
      }
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  Ok(out)
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
  let text = match input.read("events.jsonl") {
    Ok(b) => b.to_str(),
    Err(IoErr::NotFound) => "",
    Err(e) => { return Err(io_msg(e)); }
  };
  let mut applied = 0;
  let mut dups = 0;
  let mut rejected = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let Some(ev) = parse_ev(line) else {
      rejected += 1;
      continue;
    };
    let ok = apply(state, ev).map_err(kv_msg)?;
    if ok { applied += 1; } else { dups += 1; }
  }
  let bals = balances(state).map_err(kv_msg)?;
  let mut lines: List<Str> = [];
  lines.push("applied " + applied.to_str() + " duplicate " + dups.to_str() + " rejected " + rejected.to_str());
  for a in bals.keys() {
    let c = bals.get(a).unwrap_or(0);
    lines.push(a + " " + c.to_str());
  }
  Ok(lines.join("\n"))
}

fn kv_err(e: KvErr) -> Str {
  "kv error"
}

fn io_err(e: IoErr) -> Str {
  "io error"
}

fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
  let bytes = input.read("requests.txt").map_err(io_err)?;
  let text = bytes.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    let cleaned = line.replace("\t", " ").replace("\r", " ");
    let parts = cleaned.split(" ").filter(|p| p.len() > 0);
    if parts.len() != 2 {
      continue;
    }
    let Some(ts) = parts[0].parse_int() else { continue; };
    let client = parts[1];
    let window = ts / 60;
    let key = "rl:" + window.to_str() + ":" + client;
    let cur = limits.get(key).map_err(kv_err)?;
    let n = match cur {
      Some(b) => b.to_str().trim().parse_int().unwrap_or(0),
      None => 0,
    };
    if n < 3 {
      limits.add(key, 1).map_err(kv_err)?;
      out.push(parts[0] + " " + client + " allow");
    } else {
      out.push(parts[0] + " " + client + " deny");
    }
  }
  Ok(out.join("\n"))
}

struct Stat { pts: Int, played: Int }

struct Entry { name: Str, pts: Int, played: Int }

fn bump(m: Map<Str, Stat>, name: Str, pts: Int) -> Map<Str, Stat> {
  let mut m2 = m;
  let s = m2.get(name).unwrap_or(Stat { pts: 0, played: 0 });
  m2.insert(name, Stat { pts: s.pts + pts, played: s.played + 1 });
  m2
}

fn parse_stat(b: Bytes) -> Stat {
  let text = b.to_str();
  let parts = text.split(",");
  if parts.len() != 2 { return Stat { pts: 0, played: 0 }; }
  let p = parts[0].parse_int().unwrap_or(0);
  let g = parts[1].parse_int().unwrap_or(0);
  Stat { pts: p, played: g }
}

fn kv_msg(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv error: too large",
    KvErr::Full => "kv error: full",
    KvErr::NotInt => "kv error: not int",
    KvErr::Overflow => "kv error: overflow",
  }
}

fn apply(board: Kv, delta: Map<Str, Stat>) -> Result<(), Str> {
  for name in delta.keys() {
    let Some(d) = delta.get(name) else { continue; };
    let key = "p:" + name;
    let cur = match board.get(key).map_err(kv_msg)? {
      Some(b) => parse_stat(b),
      None => Stat { pts: 0, played: 0 },
    };
    let v = (cur.pts + d.pts).to_str() + "," + (cur.played + d.played).to_str();
    board.set(key, v.to_bytes()).map_err(kv_msg)?;
  }
  Ok(())
}

fn load_all(board: Kv) -> Result<List<Entry>, Str> {
  let mut out: List<Entry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = board.scan("p:", after, 1000).map_err(kv_msg)?;
    for e in page {
      let s = parse_stat(e.value);
      out.push(Entry { name: e.key.slice(2, e.key.len()), pts: s.pts, played: s.played });
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  Ok(out)
}

fn main(input: Dir, board: Kv) -> Result<Str, Str> {
  let bytes = input.read("games.txt").map_err(|e| "cannot read games.txt")?;
  let text = bytes.to_str();
  let mut delta: Map<Str, Stat> = Map::new();
  for raw in text.lines() {
    let parts = raw.trim().split(" ").filter(|p| p.len() > 0);
    if parts.len() == 2 {
      delta = bump(delta, parts[0], 3);
      delta = bump(delta, parts[1], 0);
    } else if parts.len() == 3 && parts[2] == "draw" {
      delta = bump(delta, parts[0], 1);
      delta = bump(delta, parts[1], 1);
    }
  }
  apply(board, delta)?;
  let mut all = load_all(board)?;
  all.sort_by(|a, b| {
    if a.pts != b.pts { return a.pts > b.pts; }
    if a.played != b.played { return a.played < b.played; }
    a.name < b.name
  });
  let mut lines: List<Str> = [];
  let mut i = 0;
  while i < all.len() && i < 3 {
    let e = all[i];
    lines.push((i + 1).to_str() + ". " + e.name + " " + e.pts.to_str() + " " + e.played.to_str());
    i += 1;
  }
  Ok(lines.join("\n"))
}

