struct Row { id: Int, customer: Str, product: Str, qty: Int, unit: Int }

fn parse_row(line: Str) -> Option<Row> {
  let parts = line.split(",");
  if parts.len() != 5 { return None; }
  let id = parts[0].trim().parse_int()?;
  let qty = parts[3].trim().parse_int()?;
  let unit = parts[4].trim().parse_int()?;
  Some(Row { id: id, customer: parts[1].trim(), product: parts[2].trim(), qty: qty, unit: unit })
}

fn main(input: Dir, shop: Db) -> Result<Str, Str> {
  let text = input.read("orders.csv").map_err(io_err)?.to_str();
  shop.exec("CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)", []).map_err(db_err)?;
  let lines = text.lines();
  let mut imported = 0;
  let mut skipped = 0;
  let mut rejected = 0;
  let mut first = true;
  for raw in lines {
    let line = raw.trim();
    if first {
      first = false;
      continue;
    }
    if line.len() == 0 { continue; }
    let Some(r) = parse_row(line) else {
      rejected += 1;
      continue;
    };
    let n = shop.exec(
      "INSERT OR IGNORE INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)",
      [SqlValue::Int(r.id), SqlValue::Text(r.customer), SqlValue::Text(r.product), SqlValue::Int(r.qty), SqlValue::Int(r.unit)]
    ).map_err(db_err)?;
    if n > 0 { imported += 1; } else { skipped += 1; }
  }
  let mut out: List<Str> = [];
  out.push("imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str());
  let rows = shop.query(
    "SELECT product, SUM(qty * unit_cents) AS rev, COUNT(*) FROM orders GROUP BY product ORDER BY rev DESC, product ASC LIMIT 3",
    []
  ).map_err(db_err)?;
  for row in rows {
    if row.len() < 3 { continue; }
    out.push(sv_str(row[0]) + " " + sv_str(row[1]) + " " + sv_str(row[2]));
  }
  Ok(out.join("\n"))
}

struct Agg {
  country: Str,
  customers: Int,
  orders: Int,
  revenue: Int,
  top_name: Str,
  top_rev: Int,
}

fn int_of(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn main(shop: Db) -> Result<Str, DbErr> {
  let rows = shop.query(
    "SELECT c.id, c.name, c.country, COUNT(*), SUM(o.total_cents) FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.status = 'paid' AND substr(o.placed, 1, 4) = '2026' GROUP BY c.id, c.name, c.country ORDER BY c.id",
    [],
  )?;

  let mut by_country: Map<Str, Agg> = Map::new();
  for row in rows {
    let name = text_of(row[1]);
    let country = text_of(row[2]);
    let n = int_of(row[3]);
    let rev = int_of(row[4]);
    let cur = by_country.get(country);
    let updated = match cur {
      None => Agg {
        country: country,
        customers: 1,
        orders: n,
        revenue: rev,
        top_name: name,
        top_rev: rev,
      },
      Some(a) => {
        let mut b = a;
        b.customers = b.customers + 1;
        b.orders = b.orders + n;
        b.revenue = b.revenue + rev;
        // rows come in increasing customer id, so strict > keeps the smaller id on ties
        if rev > b.top_rev {
          b.top_rev = rev;
          b.top_name = name;
        }
        b
      }
    };
    by_country.insert(country, updated);
  }

  let mut aggs: List<Agg> = [];
  for k in by_country.keys() {
    let Some(a) = by_country.get(k) else { continue; };
    aggs.push(a);
  }
  aggs.sort_by(|a, b| a.revenue > b.revenue || (a.revenue == b.revenue && a.country < b.country));

  let mut lines: List<Str> = [];
  let mut total_orders = 0;
  let mut total_rev = 0;
  for a in aggs {
    total_orders = total_orders + a.orders;
    total_rev = total_rev + a.revenue;
    lines.push(
      a.country + " customers=" + a.customers.to_str()
        + " orders=" + a.orders.to_str()
        + " revenue=" + a.revenue.to_str()
        + " top=" + a.top_name,
    );
  }
  lines.push("total orders=" + total_orders.to_str() + " revenue=" + total_rev.to_str());
  Ok(lines.join("\n"))
}

struct Batch { name: Str, lines: List<Str> }
struct Move { sku: Str, delta: Int }

