    IoErr::Exists => "io: exists",
  }
}

fn all_digits(s: Str) -> Bool {
  let b = s.to_bytes();
  if b.len() == 0 { return false; }
  for i in 0..b.len() {
    if b[i] < 48 || b[i] > 57 { return false; }
  }
  true
}

fn parse_move(line: Str) -> Option<Move> {
  let parts = line.split(" ").filter(|p| p != "");
  if parts.len() != 2 { return None; }
  let sku = parts[0];
  let amt = parts[1];
  if amt.len() < 2 { return None; }
  let sign = amt.slice(0, 1);
  let rest = amt.slice(1, amt.len());
  if !all_digits(rest) { return None; }
  let n = rest.parse_int()?;
  if n <= 0 { return None; }
  if sign == "+" {
    Some(Move { sku: sku, delta: n })
  } else if sign == "-" {
    Some(Move { sku: sku, delta: 0 - n })
  } else {
    None
  }
}

fn load_qty(db: Db, sku: Str) -> Result<Int, Str> {
  let rows = db.query("SELECT qty FROM stock WHERE sku = ?", [SqlValue::Text(sku)]).map_err(dberr)?;
  if rows.len() == 0 { return Ok(0); }
  match rows[0][0] {
    SqlValue::Int(n) => Ok(n),
    _ => Ok(0),
  }
}

fn already_applied(db: Db, name: Str) -> Result<Bool, Str> {
  let rows = db.query("SELECT 1 FROM batches WHERE name = ?", [SqlValue::Text(name)]).map_err(dberr)?;
  Ok(rows.len() > 0)
}

fn run_batch(db: Db, b: Batch) -> Result<Bool, Str> {
  let mut cur: HashMap<Str, Int> = HashMap::new();
  for line in b.lines {
    let Some(m) = parse_move(line) else { return Ok(false); };
    let q = if let Some(v) = cur.get(m.sku) { v } else { load_qty(db, m.sku)? };
    let nq = q + m.delta;
    if nq < 0 { return Ok(false); }
    cur.insert(m.sku, nq);
  }
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  for k in cur.keys() {
    let v = cur.get(k).unwrap_or(0);
    stmts.push("INSERT INTO stock(sku, qty) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty");
    params.push([SqlValue::Text(k), SqlValue::Int(v)]);
  }
  stmts.push("INSERT INTO batches(name) VALUES (?)");
  params.push([SqlValue::Text(b.name)]);
  db.transaction(stmts, params).map_err(dberr)?;
  Ok(true)
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
  stock.exec("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", []).map_err(dberr)?;
  stock.exec("CREATE TABLE IF NOT EXISTS batches (name TEXT PRIMARY KEY)", []).map_err(dberr)?;
  let text = input.read("moves.txt").map_err(ioerr)?.to_str();

  let mut batches: List<Batch> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line == "" { continue; }
    if let Some(rest) = line.strip_prefix("batch ") {
      batches.push(Batch { name: rest.trim(), lines: [] });
    } else {
      let n = batches.len();
      if n > 0 { batches[n - 1].lines.push(line); }
    }
  }

  let mut out = "";
  for b in batches {
    let status = if already_applied(stock, b.name)? {
      "skipped"
    } else if run_batch(stock, b)? {
      "applied"
    } else {
      "rejected"
    };
    out = out + b.name + " " + status + "\n";
  }

  let rows = stock.query("SELECT sku, qty FROM stock WHERE qty != 0 ORDER BY sku", []).map_err(dberr)?;
  for r in rows {
    let sku = match r[0] { SqlValue::Text(s) => s, _ => "" };
    let qty = match r[1] { SqlValue::Int(n) => n, _ => 0 };
    out = out + sku + " " + qty.to_str() + "\n";
  }
  Ok(out)
}

fn db_msg(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => "db invalid: " + m,
    DbErr::Denied => "db denied",
    DbErr::Busy => "db busy",
    DbErr::TooLarge => "db too large",
    DbErr::Constraint(m) => "db constraint: " + m,
  }
}

fn as_text(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    SqlValue::Int(n) => n.to_str(),
    SqlValue::Float(f) => f.to_str(),
    SqlValue::Null => "",
    SqlValue::Blob(b) => "",
  }
}

fn main(input: Dir, crm: Db) -> Result<Str, Str> {
  crm.exec("CREATE TABLE IF NOT EXISTS contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)", []).map_err(|e| db_msg(e))?;
  let bytes = input.read("contacts.csv").map_err(|e| "cannot read contacts.csv")?;
  let text = bytes.to_str();
  let mut inserted = 0;
  let mut updated = 0;
  let mut unchanged = 0;
  let mut rejected = 0;
  let mut first = true;
  for line in text.lines() {
    if first { first = false; continue; }
    if line.trim() == "" { continue; }
    let parts = line.split(",");
    if parts.len() != 3 { rejected += 1; continue; }
    let email = parts[0].trim().to_lowercase();
    if !email.contains("@") { rejected += 1; continue; }
    let name = parts[1].trim();
    let phone = parts[2].trim();
    let rows = crm.query("SELECT name, phone FROM contacts WHERE email = ?", [SqlValue::Text(email)]).map_err(|e| db_msg(e))?;
    if rows.len() == 0 {
      crm.exec("INSERT INTO contacts (email, name, phone) VALUES (?, ?, ?)", [SqlValue::Text(email), SqlValue::Text(name), SqlValue::Text(phone)]).map_err(|e| db_msg(e))?;
      inserted += 1;
    } else {
      let old_name = as_text(rows[0][0]);
      let old_phone = as_text(rows[0][1]);
      if old_name != name || old_phone != phone {
        crm.exec("UPDATE contacts SET name = ?, phone = ? WHERE email = ?", [SqlValue::Text(name), SqlValue::Text(phone), SqlValue::Text(email)]).map_err(|e| db_msg(e))?;
        updated += 1;
      } else {
        unchanged += 1;
      }
    }
  }
  let crows = crm.query("SELECT COUNT(*) FROM contacts", []).map_err(|e| db_msg(e))?;
  let mut total = 0;
  if crows.len() > 0 {
    if let SqlValue::Int(n) = crows[0][0] { total = n; }
  }
  let mut out = "inserted " + inserted.to_str() + " updated " + updated.to_str() + " unchanged " + unchanged.to_str() + " rejected " + rejected.to_str() + "\n";
  out = out + "contacts " + total.to_str();
  let missing = crm.query("SELECT email FROM contacts WHERE phone = '' ORDER BY email", []).map_err(|e| db_msg(e))?;
  let mut emails: List<Str> = [];
  for r in missing { emails.push(as_text(r[0])); }
  emails.sort();
  for e in emails { out = out + "\nmissing phone: " + e; }
  Ok(out)
}

struct Reply { status: Int, body: Json }

struct Entry { name: Str, count: Int }

fn obj(name: Str, count: Int) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(name));
  m.insert("count", Json::Num(count));
  Json::Obj(m)
}

fn error(status: Int, msg: Str) -> Reply {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Reply { status: status, body: Json::Obj(m) }
}

fn valid_name(name: Str) -> Bool {
  let b = name.to_bytes();
  if b.len() < 1 || b.len() > 32 { return false; }
  for i in 0..b.len() {
    let c = b[i];
    let ok = (c >= 97 && c <= 122) || (c >= 48 && c <= 57) || c == 45;
    if !ok { return false; }
  }
  true
}

fn top(counts: Kv) -> Result<Reply, KvErr> {
  let mut entries: List<Entry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = counts.scan("c/", after, 1000)?;
    for e in page {
      let name = e.key.slice(2, e.key.len());
      let n = e.value.to_str().parse_int().unwrap_or(0);
      entries.push(Entry { name: name, count: n });
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  entries.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.name < b.name));
  let mut out: List<Json> = [];
  let mut i = 0;
  while i < entries.len() && i < 3 {
    out.push(obj(entries[i].name, entries[i].count));
    i = i + 1;
  }
  Ok(Reply { status: 200, body: Json::Arr(out) })
}

fn handle(method: Str, target: Str, counts: Kv) -> Result<Reply, KvErr> {
  if target == "/top" {
    if method == "GET" { return top(counts); }
    return Ok(error(404, "not found"));
  }
  if let Some(name) = target.strip_prefix("/hit/") {
    if method != "POST" { return Ok(error(404, "not found")); }
    if !valid_name(name) { return Ok(error(400, "bad name")); }
    let n = counts.add("c/" + name, 1)?;
    return Ok(Reply { status: 200, body: obj(name, n) });
  }
  if let Some(name) = target.strip_prefix("/count/") {
    if method != "GET" { return Ok(error(404, "not found")); }
    if !valid_name(name) { return Ok(error(400, "bad name")); }
    let v = counts.get("c/" + name)?;
    let n = match v {
      Some(b) => b.to_str().parse_int().unwrap_or(0),
      None => 0,
    };
    return Ok(Reply { status: 200, body: obj(name, n) });
  }
  Ok(error(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Str {
  let r = match handle(req.method(), req.target(), counts) {
    Ok(r) => r,
    Err(_) => error(500, "internal error"),
  };
  let sent = res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes());
  match sent {
    Ok(()) => r.status.to_str(),
    Err(_) => "send failed",
  }
}

