fn in_range(b: Bytes, i: Int, lo: Int, hi: Int) -> Bool {
  if i >= b.len() { return false; }
  b[i] >= lo && b[i] <= hi
}

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 {
      i += 1;
    } else if c >= 194 && c <= 223 {
      if !in_range(b, i + 1, 128, 191) { return false; }
      i += 2;
    } else if c == 224 {
      if !in_range(b, i + 1, 160, 191) || !in_range(b, i + 2, 128, 191) { return false; }
      i += 3;
    } else if (c >= 225 && c <= 236) || c == 238 || c == 239 {
      if !in_range(b, i + 1, 128, 191) || !in_range(b, i + 2, 128, 191) { return false; }
      i += 3;
    } else if c == 237 {
      if !in_range(b, i + 1, 128, 159) || !in_range(b, i + 2, 128, 191) { return false; }
      i += 3;
    } else if c == 240 {
      if !in_range(b, i + 1, 144, 191) || !in_range(b, i + 2, 128, 191) || !in_range(b, i + 3, 128, 191) { return false; }
      i += 4;
    } else if c >= 241 && c <= 243 {
      if !in_range(b, i + 1, 128, 191) || !in_range(b, i + 2, 128, 191) || !in_range(b, i + 3, 128, 191) { return false; }
      i += 4;
    } else if c == 244 {
      if !in_range(b, i + 1, 128, 143) || !in_range(b, i + 2, 128, 191) || !in_range(b, i + 3, 128, 191) { return false; }
      i += 4;
    } else {
      return false;
    }
  }
  true
}

fn body_json(b: Bytes) -> Option<Json> {
  if !valid_utf8(b) { return None; }
  b.to_str().parse_json().ok()
}

fn decode(b: Bytes) -> Option<Todo> {
  let j = body_json(b)?;
  let id = j.get("id")?.as_int()?;
  let title = j.get("title")?.as_str()?;
  let done = j.get("done")?.as_bool()?;
  Some(Todo { id: id, title: title, done: done })
}

fn create(store: Kv, body: Bytes) -> Result<Resp, KvErr> {
  let mut title = "";
  match body_json(body) {
    Some(Json::Obj(m)) => {
      match m.get("title") {
        Some(Json::Str(s)) => { title = s.trim(); }
        _ => {}
      }
    }
    _ => {}
  }
  if title.len() == 0 { return Ok(resp(400, err_body("title required"))); }
  let id = store.add("next_id", 1)?;
  let t = Todo { id: id, title: title, done: false };
  store.set(tkey(id), encode(t).to_bytes())?;
  Ok(resp(201, encode(t)))
}

fn list(store: Kv, filter: Option<Bool>) -> Result<Resp, KvErr> {
  let mut out: List<Json> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = store.scan("todo/", after, 1000)?;
    for e in page {
      if let Some(t) = decode(e.value) {
        let keep = match filter {
          Some(d) => t.done == d,
          None => true,
        };
        if keep { out.push(to_json(t)); }
      }
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  Ok(resp(200, Json::Arr(out).to_json()))
}

fn get_one(store: Kv, id: Int) -> Result<Resp, KvErr> {
  let Some(b) = store.get(tkey(id))? else { return Ok(not_found()); };
  let Some(t) = decode(b) else { return Ok(not_found()); };
  Ok(resp(200, encode(t)))
}

fn apply(t: Todo, body: Option<Json>) -> Option<Todo> {
  let mut out = t;
  match body {
    Some(Json::Obj(m)) => {
      match m.get("title") {
        None => {}
        Some(Json::Str(s)) => {
          let tr = s.trim();
          if tr.len() == 0 { return None; }
          out.title = tr;
        }
        Some(_) => { return None; }
      }
      match m.get("done") {
        None => {}
        Some(Json::Bool(d)) => { out.done = d; }
        Some(_) => { return None; }
      }
      Some(out)
    }
    _ => None,
  }
}

fn patch(store: Kv, id: Int, body: Bytes) -> Result<Resp, KvErr> {
  let k = tkey(id);
  let parsed = body_json(body);
  loop {
    let Some(b) = store.get(k)? else { return Ok(not_found()); };
    let Some(t) = decode(b) else { return Ok(not_found()); };
    let Some(t2) = apply(t, parsed) else { return Ok(resp(400, err_body("bad update"))); };
    if store.swap(k, Some(b), Some(encode(t2).to_bytes()))? {
      return Ok(resp(200, encode(t2)));
    }
  }
}

fn remove(store: Kv, id: Int) -> Result<Resp, KvErr> {
  let k = tkey(id);
  let Some(_b) = store.get(k)? else { return Ok(not_found()); };
  store.delete(k)?;
  Ok(resp(204, ""))
}

fn parse_id(s: Str) -> Option<Int> {
  let n = s.parse_int()?;
  if n < 1 || n.to_str() != s { return None; }
  Some(n)
}

fn route(req: Incoming, store: Kv) -> Result<Resp, KvErr> {
  let method = req.method();
  let target = req.target();
  let mut path = target;
  let mut query = "";
  match target.find("?") {
    Some(i) => {
      path = target.slice(0, i);
      query = target.slice(i + 1, target.len());
    }
    None => {}
  }
  if path == "/todos" {
    if method == "GET" {
      let mut filter: Option<Bool> = None;
      for part in query.split("&") {
        if part == "done=true" { filter = Some(true); }
        else if part == "done=false" { filter = Some(false); }
      }
      return list(store, filter);
    }
    if method == "POST" { return create(store, req.body()); }
    return Ok(not_found());
  }
  let Some(ids) = path.strip_prefix("/todos/") else { return Ok(not_found()); };
  let Some(id) = parse_id(ids) else { return Ok(not_found()); };
  if method == "GET" { return get_one(store, id); }
  if method == "PATCH" { return patch(store, id, req.body()); }
  if method == "DELETE" { return remove(store, id); }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Str {
  let r = match route(req, store) {
    Ok(r) => r,
    Err(_) => resp(500, err_body("storage error")),
  };
  let sent = if r.body.len() == 0 {
    res.send(r.status, [], [], "".to_bytes())
  } else {
    res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())
  };
  if sent.is_err() { return "send failed"; }
  r.status.to_str()
}

struct Resp { status: Int, body: Json }

struct NewNote { title: Str, body: Str, tags: List<Str> }

struct Note { id: Int, title: Str, body: Str, tags: List<Str> }

fn err(status: Int, msg: Str) -> Resp {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Resp { status: status, body: Json::Obj(m) }
}

fn not_found() -> Resp { err(404, "not found") }

fn parse_id(s: Str) -> Option<Int> {
  if s.len() == 0 || s.len() > 18 { return None; }
  let n = s.parse_int()?;
  if n <= 0 || n.to_str() != s { return None; }
  Some(n)
}

fn parse_note(b: Bytes) -> Option<NewNote> {
  let text = b.to_str();
  let doc = text.parse_json().ok()?;
  let obj = doc.as_map()?;
  let title = obj.get("title")?.as_str()?;
  if title.len() == 0 { return None; }
  let body = obj.get("body")?.as_str()?;
  let mut tags: List<Str> = [];
  if let Some(t) = obj.get("tags") {
    let items = t.as_list()?;
    for it in items {
      let s = it.as_str()?.to_lowercase();
      if !tags.contains(s) { tags.push(s); }
    }
  }
  Some(NewNote { title: title, body: body, tags: tags })
}

fn sql_int(v: SqlValue) -> Option<Int> {
  match v { SqlValue::Int(n) => Some(n), _ => None }
}

fn sql_text(v: SqlValue) -> Option<Str> {
  match v { SqlValue::Text(s) => Some(s), _ => None }
}

fn decode(row: List<SqlValue>) -> Option<Note> {
  if row.len() < 4 { return None; }
  let id = sql_int(row[0])?;
  let title = sql_text(row[1])?;
  let body = sql_text(row[2])?;
  let tags_text = sql_text(row[3])?;
  let mut tags: List<Str> = [];
  let parsed = tags_text.parse_json().ok()?;
  for j in parsed.as_list()? {
    tags.push(j.as_str()?);
  }
  Some(Note { id: id, title: title, body: body, tags: tags })
}

fn note_json(n: Note) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(n.id));
  m.insert("title", Json::Str(n.title));
  m.insert("body", Json::Str(n.body));
  m.insert("tags", Json::Arr(n.tags.map(|s| Json::Str(s))));
  Json::Obj(m)
}

fn create(db: Db, b: Bytes) -> Result<Resp, DbErr> {
  let Some(n) = parse_note(b) else { return Ok(err(400, "invalid note")); };
  let tags = Json::Arr(n.tags.map(|s| Json::Str(s))).to_json();
  let rows = db.query(
    "INSERT INTO notes (title, body, tags) VALUES (?, ?, ?) RETURNING id",
    [SqlValue::Text(n.title), SqlValue::Text(n.body), SqlValue::Text(tags)])?;
  let mut id = 0;
  if rows.len() > 0 && rows[0].len() > 0 {
    if let SqlValue::Int(v) = rows[0][0] { id = v; }
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  Ok(Resp { status: 201, body: Json::Obj(m) })
}

fn list(db: Db, query: Str) -> Result<Resp, DbErr> {
  let mut tag: Option<Str> = None;
  let mut q: Option<Str> = None;
  if query.len() > 0 {
    for part in query.split("&") {
      let kv = part.split("=");
      if kv.len() == 2 {
        if kv[0] == "tag" {
          tag = Some(kv[1].to_lowercase());
        } else if kv[0] == "q" {
          q = Some(kv[1]);
        }
      }
    }
  }
  let rows = db.query("SELECT id, title, body, tags FROM notes ORDER BY id DESC", [])?;
  let mut out: List<Json> = [];
  for row in rows {
    let Some(n) = decode(row) else { continue; };
    if let Some(t) = tag {
      if !n.tags.contains(t) { continue; }
    }
    if let Some(w) = q {
      if !n.title.contains(w) && !n.body.contains(w) { continue; }
    }
    let mut m: Map<Str, Json> = Map::new();
    m.insert("id", Json::Num(n.id));
    m.insert("title", Json::Str(n.title));
    out.push(Json::Obj(m));
  }
  Ok(Resp { status: 200, body: Json::Arr(out) })
}

fn get_one(db: Db, id: Int) -> Result<Resp, DbErr> {
  let rows = db.query("SELECT id, title, body, tags FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 { return Ok(not_found()); }
  let Some(n) = decode(rows[0]) else { return Ok(not_found()); };
  Ok(Resp { status: 200, body: note_json(n) })
}

fn delete_one(db: Db, id: Int) -> Result<Resp, DbErr> {
  let changed = db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if changed == 0 { return Ok(not_found()); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("deleted", Json::Num(id));
  Ok(Resp { status: 200, body: Json::Obj(m) })
}

fn handle(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)", [])?;
  let method = req.method();
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  if path == "/notes" {
    if method == "GET" { return list(db, query); }
    if method == "POST" { return create(db, req.body()); }
    return Ok(not_found());
  }
  let Some(rest) = path.strip_prefix("/notes/") else { return Ok(not_found()); };
  let Some(id) = parse_id(rest) else { return Ok(not_found()); };
  if method == "GET" { return get_one(db, id); }
  if method == "DELETE" { return delete_one(db, id); }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
  let r = match handle(req, db) {
    Ok(r) => r,
    Err(_) => err(500, "internal error"),
  };
  match res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes()) {
    Ok(_) => Ok("ok"),
    Err(_) => Err("send failed"),
  }
}

struct Station { id: Str, name: Str }

fn fmt(t: Int) -> Str {
  let neg = t < 0;
  let a = if neg { 0 - t } else { t };
  let s = (a / 10).to_str() + "." + (a % 10).to_str();
  if neg { "-" + s } else { s }
}

fn readings(api: Http, id: Str) -> Option<List<Int>> {
  let body = api.get("/stations/" + id + "/readings").ok()?;
  let doc = body.to_str().parse_json().ok()?;
  let arr = doc.get("readings")?.as_list()?;
  let mut temps: List<Int> = [];
  for r in arr {
    let t = r.get("temp")?.as_int()?;
    temps.push(t);
  }
  Some(temps)
}

fn summary(name: Str, temps: List<Int>) -> Str {
  if temps.len() == 0 {
    return name + " no data";
  }
  let mut mn = temps[0];
  let mut mx = temps[0];
  let mut sum = 0;
  for t in temps {
    mn = mn.min(t);
    mx = mx.max(t);
    sum = sum + t;
  }
  let n = temps.len();
  let avg = sum / n;
  name + " min=" + fmt(mn) + " max=" + fmt(mx) + " avg=" + fmt(avg) + " n=" + n.to_str()
}

fn main(api: Http) -> Result<Str, Str> {
  let body = match api.get("/stations") {
    Ok(b) => b,
    Err(_) => return Err("stations request failed"),
  };
  let doc = body.to_str().parse_json()?;
  let list = match doc.get("stations").and_then(|j| j.as_list()) {
    Some(l) => l,
    None => return Err("missing stations"),
  };
  let mut stations: List<Station> = [];
  for s in list {
    let Some(id) = s.get("id").and_then(|j| j.as_str()) else { continue; };
    let Some(name) = s.get("name").and_then(|j| j.as_str()) else { continue; };
    stations.push(Station { id: id, name: name });
  }
  stations.sort_by_key(|s| s.name);
  let mut lines: List<Str> = [];
  for s in stations {
    match readings(api, s.id) {
      Some(temps) => lines.push(summary(s.name, temps)),
      None => lines.push(s.name + " unavailable"),
    }
  }
  Ok(lines.join("\n"))
}

fn http_err(e: HttpErr) -> Str {
  match e {
    HttpErr::Denied => "http: denied",
    HttpErr::Timeout => "http: timeout",
    HttpErr::TooLarge => "http: too large",
    HttpErr::Status(n) => "http: status " + n.to_str(),
    HttpErr::Invalid => "http: invalid request",
  }
}

fn main(api: Http) -> Result<Str, Str> {
  let mut page = 1;
  let mut count = 0;
  let mut refunded = 0;
  let mut paid: Map<Str, Int> = Map::new();
  let mut best_id: Option<Int> = None;
  let mut best_cents = 0;
  let mut pages_read = 0;

  loop {
    let body = api.get("/orders?page=" + page.to_str()).map_err(http_err)?;
    let doc = body.to_str().parse_json()?;
    let orders = doc.get("orders").and_then(|j| j.as_list()).unwrap_or([]);
    for o in orders {
      count += 1;
      let id = o.get("id").and_then(|j| j.as_int()).unwrap_or(0);
      let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
      let cents = o.get("cents").and_then(|j| j.as_int()).unwrap_or(0);
      let currency = o.get("currency").and_then(|j| j.as_str()).unwrap_or("");
      if status == "paid" {
        let cur = paid.get(currency).unwrap_or(0);
        paid.insert(currency, cur + cents);
        match best_id {
          None => {
            best_id = Some(id);
            best_cents = cents;
          }
          Some(b) => {
            if cents > best_cents || (cents == best_cents && id < b) {
              best_id = Some(id);
              best_cents = cents;
            }
          }
        }
      } else if status == "refunded" {
        refunded += 1;
      }
    }
    pages_read += 1;
    if pages_read > 100000 {
      return Err("too many pages");
    }
    match doc.get("next") {
      Some(Json::Num(n)) => {
        page = n;
      }
      _ => break,
    }
  }

  let mut paid_json: Map<Str, Json> = Map::new();
  for k in paid.keys() {
    paid_json.insert(k, Json::Num(paid.get(k).unwrap_or(0)));
  }
  let mut obj: Map<Str, Json> = Map::new();
  obj.insert("orders", Json::Num(count));
  obj.insert("paid_cents", Json::Obj(paid_json));
  obj.insert("refunded", Json::Num(refunded));
  let largest = match best_id {
    Some(b) => Json::Num(b),
    None => Json::Null,
  };
  obj.insert("largest", largest);
  let payload = Json::Obj(obj).to_json();

  let r = api
    .send("POST", "/summaries", ["content-type: application/json"], payload.to_bytes())
    .map_err(http_err)?;
  if r.status != 201 {
    return Err("summary POST answered status " + r.status.to_str());
  }
  let resp = r.body.to_str().parse_json()?;
  let id = resp.get("id").and_then(|j| j.as_str()).ok_or("response has no id")?;
  Ok(id)
}
